import React, { useState, useEffect, useRef } from "react";
import emailjs from "@emailjs/browser";
import "./brutalist-button.css";

/* ================= MAIN APP ================= */

export default function ValentineApp() {

    const [page, setPage] = useState("home");

    useEffect(() => {

        emailjs.init("aEbujbuY5ZtX1sDQq");

    }, []);


    return (
        <div className="valentine-container">


            {/* ===== HEART BACKGROUND ===== */}
            <div className="hearts-bg">
                <div className="heart x1" />
                <div className="heart x2" />
                <div className="heart x3" />
                <div className="heart x4" />
                <div className="heart x5" />
                <div className="altheart x6" />
            </div>


            {/* ===== CONTENT ===== */}
            <div className="app-content">

                {page === "home" && (
                    <HomePage onYes={() => setPage("game")} />
                )}

                {page === "game" && (
                    <DinoGamePage />
                )}

            </div>


            {/* ===== STYLES ===== */}
            <style>{styles}</style>

        </div>
    );
}


/* ================= HOME ================= */

function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });

    const btnRef = useRef(null);

    const move = () => {

        const btn = btnRef.current;

        if (!btn) return;

        const btnWidth = btn.offsetWidth;
        const btnHeight = btn.offsetHeight;

        const padding = 200; // distance from edges

        const maxX = window.innerWidth - btnWidth - padding;
        const maxY = window.innerHeight - btnHeight - padding;

        const x = Math.random() * maxX - maxX / 2;
        const y = Math.random() * maxY - maxY / 2;


        setPos({ x, y });
    };


    return (
        <div className="home-page">

            <h1 className="title">
                Will you be my Valentine? 💝
            </h1>

            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>


            {/* NO BUTTON WRAPPER */}
            <div className="no-wrapper">

                <button
                    ref={btnRef}
                    className="brutalist-button button-1 no-brutal"
                    onMouseEnter={move}
                    onClick={move}
                    onTouchStart={move}
                    style={{
                        transform: `translate(${pos.x}px, ${pos.y}px)`
                    }}
                >
                    NO 😜
                </button>

            </div>

        </div>
    );
}



/* ================= GAME + MESSAGE ================= */

function DinoGamePage() {

    const [started, setStarted] = useState(false);

    const [senderName, setSenderName] = useState("");
    const [message, setMessage] = useState("");

    const [sending, setSending] = useState(false);
    const [sent, setSent] = useState(false);

    const iframeRef = useRef(null);
    const [key, setKey] = useState(0);


    /* ---------- SEND EMAIL ---------- */

    const sendMessage = async () => {

        if (!senderName.trim() || !message.trim()) {
            alert("Please enter name & message 💕");
            return;
        }

        setSending(true);

        try {

            await emailjs.send(
                "service_1z5tkws",
                "template_1xkowsi",
                {
                    user_name: senderName,
                    message: message,
                },
                "aEbujbuY5ZtX1sDQq"
            );

            setSent(true);
            setMessage("");
            setSenderName("");

        } catch (err) {

            console.error(err);
            alert("Message failed 💔");

        }

        setSending(false);
    };


    /* ---------- START GAME ---------- */

    const startGame = () => {

        setStarted(true);
        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };


    /* ---------- RETRY ---------- */

    const retryGame = () => {

        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };


    return (
        <div className="game-page">


            {/* ===== MESSAGE BOX ===== */}
            {!started && (

                <div className="message-box">

                    <h4>Send me a message 💌</h4>

                    <input
                        value={senderName}
                        onChange={e => setSenderName(e.target.value)}
                        placeholder="Your name 💖"
                        className="text-input"
                    />

                    <textarea
                        value={message}
                        onChange={e => setMessage(e.target.value)}
                        placeholder="Your message..."
                        rows={4}
                        className="text-input"
                        style={{ resize: "none" }}
                    />

                    <button
                        onClick={sendMessage}
                        disabled={sending || sent}
                        className="brutalist-button button-1 no-brutal"
                        style={{ width: "100%" }}
                    >
                        {sent ? "💖 Sent!" : sending ? "Sending..." : "Send 💌"}
                    </button>

                </div>
            )}


            {/* ===== START ===== */}
            {!started && (

                <button
                    className="brutalist-button button-1 no-brutal"
                    onClick={startGame}
                >
                    ▶ Start Game
                </button>
            )}


            {/* ===== GAME ===== */}
            {started && (

                <>

                    <div className="game-frame">

                        <iframe
                            key={key}
                            ref={iframeRef}
                            src="/dino.html"
                            title="Papa Game"
                            tabIndex="0"
                        />

                    </div>


                    <button
                        className="brutalist-button button-1 no-brutal"
                        onClick={retryGame}
                    >
                        🔄 Retry
                    </button>

                </>
            )}


            <p style={{ opacity: 0.7 }}>

                {!started
                    ? "If you are bored, press Start 😄"
                    : "Press SPACE to Jump or Press arrow keys to jump or duck"}

            </p>


        </div>
    );
}


/* ================= STYLES ================= */

const styles = `

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Quicksand", sans-serif;
}

.valentine-container {
  min-height: 100vh;
  background: linear-gradient(135deg,#FFE5EC,#FFCDB2,#E4C1F9);
  position: relative;
  overflow: hidden;
}


/* LAYERS */

.hearts-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.app-content {
  position: relative;
  z-index: 5;
}


/* HOME */

.home-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 40px;
  text-align: center;
}

.title {
  font-family: "Pacifico";
  font-size: clamp(2.5rem,6vw,4rem);
  color: #ff6b9d;
}


/* GAME */

.game-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.game-frame {
  width: 100%;
  max-width: 1200px;
  aspect-ratio: 1200 / 445;
  border: 3px solid #ff6b9d;
  border-radius: 15px;
  overflow: hidden;
  background: black;
}

.game-frame iframe {
  width: 100%;
  height: 100%;
  border: none;
}


/* MESSAGE BOX */

.message-box {
  width: 100%;
  max-width: 420px;
  background: white;
  padding: 20px;
  border-radius: 15px;
  box-shadow: 0 10px 25px rgba(255,107,157,.25);
  text-align: center;
}

.message-box h4 {
  color: #ff6b9d;
  margin-bottom: 10px;
}

.text-input {
  width: 100%;
  padding: 12px;
  border-radius: 10px;
  border: 2px solid #ffb3c6;
  margin-top: 8px;
}

.no-wrapper {
  position: relative;
  display: inline-block;
}


.no-brutal {
  transition: transform 0.15s ease;
}


`;
